<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,reactive,ref} from 'vue'
import {useRoute} from 'vue-router'
import {ElMessageBox,ElMessage} from 'element-plus'
import * as api from '../api/delivery'
import type {Release,Releases} from '../api/delivery'
import * as training from '../api/training'
import type {Model} from '../api/training'
import {organizations} from '../api/workbench'
import {session} from '../session'
const route=useRoute(),admin=computed(()=>session.user?.role==='ADMIN'),data=ref<Releases>(),page=ref(1),error=ref(''),busy=ref(false),departments=ref<Array<{organizationId:string;name:string}>>([]),models=ref<Model[]>([]),evaluations=ref<Array<{runId:string;name:string}>>([]),predictionResult=ref<api.ReleasedResult>()
const form=reactive({organizationId:'0',scene:'TEXT_REUSE',name:'',modelId:String(route.query.modelId??''),evaluationId:'',preset:'CURRENT'}),prediction=reactive({organizationId:'',sentence1:'',sentence2:''})
async function chooseModel(){form.evaluationId='';evaluations.value=form.modelId?await api.releaseEvaluations(form.modelId):[]}
async function searchModels(q:string){try{models.value=(await training.models(1,q)).items}catch(v){error.value=v instanceof Error?v.message:'读取模型失败'}}
let timer:ReturnType<typeof setInterval>|undefined,alive=true,refreshing=false
async function load(){if(refreshing)return;refreshing=true;try{const value=await api.releases(page.value);if(alive)data.value=value}catch(v){error.value=v instanceof Error?v.message:'读取版本失败'}finally{refreshing=false}}
async function perform(task:()=>Promise<void>){busy.value=true;error.value='';try{await task()}catch(v){error.value=v instanceof Error?v.message:'操作未完成'}finally{busy.value=false}}
function expected(row:Release){return data.value?.pointers.find(p=>p.scopeKey===`${row.organizationId}:${row.scene}`)?.releaseId??''}
async function register(){await perform(async()=>{if(!form.name.trim())throw new Error('请填写版本名称');await api.createRelease({...form});ElMessage.success('已提交核验');await load()})}
async function switchVersion(row:Release){try{await ElMessageBox.confirm(`将${row.department}的${api.sceneNames[row.scene]}切换为“${row.name}”？`,'发布 / 回退',{confirmButtonText:'确认切换',cancelButtonText:'取消'})}catch{return}await perform(async()=>{await api.activate(row.id,expected(row));ElMessage.success('活动版本已切换');await load()})}
async function removeOverride(row:Release){try{await ElMessageBox.confirm('确认撤销该场景的专用版本，恢复默认选择？','恢复默认',{confirmButtonText:'恢复默认',cancelButtonText:'取消'})}catch{return}await perform(async()=>{await api.reset(row.organizationId,row.scene,expected(row));await load()})}
async function predict(){await perform(async()=>{if(!prediction.organizationId||!prediction.sentence1.trim()||!prediction.sentence2.trim())throw new Error('请选择部门并填写两段文本');predictionResult.value=await api.releasedPredict(prediction.organizationId,[{sentence1:prediction.sentence1,sentence2:prediction.sentence2}])})}
const releaseName=(id:string|null)=>id?data.value?.items.find(r=>r.id===id)?.name??id.slice(0,8):'默认选择'
onMounted(()=>{void perform(async()=>{const [orgs,modelList]=await Promise.all([organizations(),training.models()]);departments.value=orgs;prediction.organizationId=orgs[0]?.organizationId??'';models.value=modelList.items;if(form.modelId)await chooseModel();await load()});timer=setInterval(()=>void load(),3000)});onBeforeUnmount(()=>{alive=false;if(timer)clearInterval(timer)})
</script>
<template><el-alert v-if="error" :title="error" type="error" :closable="false"/><section class="panel"><div class="section-heading"><h2>活动版本</h2><el-button @click="load">刷新</el-button></div><div class="release-pointers"><div v-for="p in data?.pointers.filter(p=>p.releaseId)" :key="p.scopeKey"><span>{{p.scopeKey.startsWith('0:')?'校级默认':departments.find(d=>d.organizationId===p.scopeKey.split(':')[0])?.name}} · {{api.sceneNames[p.scopeKey.split(':')[1]!]}}</span><strong>{{releaseName(p.releaseId)}}</strong></div></div><el-empty v-if="!data?.pointers.some(p=>p.releaseId)" description="当前沿用默认审核配置，可登记版本后发布" :image-size="60"/></section>
<section v-if="admin" class="panel"><h2>登记发布版本</h2><el-form label-position="top"><div class="release-form"><el-form-item label="版本名称"><el-input v-model="form.name" maxlength="120"/></el-form-item><el-form-item label="使用范围"><el-select v-model="form.organizationId"><el-option value="0" label="校级默认"/><el-option v-for="d in departments" :key="d.organizationId" :value="d.organizationId" :label="d.name"/></el-select></el-form-item><el-form-item label="使用场景"><el-select v-model="form.scene"><el-option v-for="(name,key) in api.sceneNames" :key="key" :value="key" :label="name"/></el-select></el-form-item><el-form-item v-if="form.scene==='TEXT_REUSE'" label="兼容审核配置"><el-select v-model="form.preset"><el-option value="CURRENT" label="句子对齐语义审核"/><el-option value="LEGACY" label="原有字面审核配置"/></el-select></el-form-item><template v-else><el-form-item label="已训练模型"><el-select v-model="form.modelId" filterable remote :remote-method="searchModels" @change="perform(chooseModel)"><el-option v-for="m in models" :key="m.modelId" :value="m.modelId" :label="m.name"/></el-select></el-form-item><el-form-item label="独立评价"><el-select v-model="form.evaluationId" placeholder="先在模型管理完成独立评价"><el-option v-for="r in evaluations" :key="r.runId" :value="r.runId" :label="r.name || r.runId.slice(0,8)"/></el-select></el-form-item></template></div></el-form><el-button type="primary" :loading="busy" @click="register">核验并登记</el-button><RouterLink to="/models" class="link-gap">查看模型及评价</RouterLink></section>
<section class="panel"><h2>发布版本与回退</h2><el-table :data="data?.items ?? []" empty-text="暂无发布版本"><el-table-column prop="name" label="版本" min-width="180"/><el-table-column prop="department" label="范围" min-width="140"/><el-table-column label="场景" width="120"><template #default="{row}">{{api.sceneNames[row.scene]}}</template></el-table-column><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="expected(row)===row.id?'success':row.status==='FAILED'?'danger':'info'">{{expected(row)===row.id?'使用中':api.deliveryStates[row.status]}}</el-tag></template></el-table-column><el-table-column label="核验与评价" min-width="220"><template #default="{row}"><span v-if="row.error" class="unsaved">{{row.error}}</span><span v-else-if="row.manifest?.metrics">Macro-F1 {{(row.manifest.metrics.macro_f1*100).toFixed(2)}}% · 阈值 {{row.manifest.threshold}}</span><span v-else>{{row.manifest?.textConfig?.method || '等待核验'}}</span></template></el-table-column><el-table-column v-if="admin" label="操作" width="200"><template #default="{row}"><el-button link :disabled="busy||row.status!=='READY'||expected(row)===row.id" @click="switchVersion(row)">发布 / 回退</el-button><el-button v-if="expected(row)===row.id" link :disabled="busy" @click="removeOverride(row)">恢复默认</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="data?.total??0" :page-size="20" layout="total,prev,pager,next" @current-change="load"/></section>
<section class="panel"><h2>使用已发布模型预测</h2><el-form label-position="top"><el-form-item label="使用部门"><el-select v-model="prediction.organizationId"><el-option v-for="d in departments" :key="d.organizationId" :value="d.organizationId" :label="d.name"/></el-select></el-form-item><div class="prediction-pair"><el-form-item label="原文"><el-input v-model="prediction.sentence1" type="textarea" :rows="3"/></el-form-item><el-form-item label="待比对文本"><el-input v-model="prediction.sentence2" type="textarea" :rows="3"/></el-form-item></div></el-form><el-button type="primary" :loading="busy" @click="predict">按活动版本预测</el-button><div v-if="predictionResult" class="release-pointers"><div><span>发布版本 {{predictionResult.releaseId.slice(0,8)}}</span><strong>{{predictionResult.rows[0]?.predicted===1?'语义相近':'语义不同'}}</strong></div><div><span>{{predictionResult.rows[0]?.scoreType==='margin'?'间隔分数':'模型分数'}}</span><strong>{{predictionResult.rows[0]?.score.toFixed(4)}}</strong></div></div></section>
<section class="panel"><h2>切换记录</h2><el-table :data="data?.history??[]" empty-text="暂无切换记录"><el-table-column label="范围 / 场景" min-width="190"><template #default="{row}">{{row.scopeKey}}</template></el-table-column><el-table-column label="原版本" min-width="180"><template #default="{row}">{{releaseName(row.previousId)}}</template></el-table-column><el-table-column label="切换至" min-width="180"><template #default="{row}">{{releaseName(row.releaseId)}}</template></el-table-column><el-table-column label="时间" min-width="180"><template #default="{row}">{{new Date(row.createdAt).toLocaleString('zh-CN')}}</template></el-table-column></el-table></section></template>
<style scoped>.release-form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.release-form .el-select{width:100%}.release-pointers{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.release-pointers>div{border:1px solid var(--line);padding:20px;background:color-mix(in srgb,var(--el-color-primary) 6%,var(--canvas))}.release-pointers span{display:block;color:var(--muted);font-size:12px}.release-pointers strong{display:block;font-size:23px;margin-top:12px}.prediction-pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}.link-gap{margin-left:18px}@media(max-width:1000px){.release-form{grid-template-columns:1fr 1fr}}@media(max-width:700px){.release-form,.release-pointers,.prediction-pair{grid-template-columns:1fr}}</style>
